components.template:
@if (displayStateSelection() && stateObject) {
  <mat-select class="default-state-controller" [attr.aria-label]="'dashboard.state' | translate" [(ngModel)]="stateObject[0].id">
    @for (stateId of stateIds(); track stateId) {
      <mat-option [value]="stateId">
        {{ getStateName(stateId, states[stateId]) }}
      </mat-option>
    }
  </mat-select>
}

@if (stateObject) {
  <div class="entity-state-controller" layout="row" layout-align="start center">
    @if (!dashboardCtrl.isMobile || stateObject.length === 1) {
      <div layout="row" layout-align="start center">
        @for (state of stateObject; track $index; let last = $last) {
          <span class="state-entry" [style.fontWeight]="last ? 'bold' : 'normal'" [style.cursor]="last ? 'default' : 'pointer'" (click)="navigatePrevState($index)">
            {{ getStateName($index) }}
            <span class="state-divider" [hidden]="last"> &gt; </span>
          </span>
        }
      </div>
    }
    @if (dashboardCtrl.isMobile && stateObject.length > 1) {
      <mat-select [attr.aria-label]="'dashboard.state' | translate" [(ngModel)]="selectedStateIndex" (ngModelChange)="navigatePrevState($event)">
        @for (state of stateObject; track $index) {
          <mat-option [value]="$index">
            {{ getStateName($index) }}
          </mat-option>
        }
      </mat-select>
    }
  </div>
}

@let all = steps();
<div flex layout="row" layout-align="start center" class="tb-breadcrumb">
  @if (all.length) {
    <h1 flex hide-gt-sm>{{ all[all.length - 1].label | breadcrumbLabel }}</h1>
  }
  @for (step of all; track step.name; let last = $last) {
    <span hide-xs hide-sm>
      @if (!last) {
        <a [routerLink]="step.link">
          @if (step.label | breadcrumbIcon; as icon) {
            <mat-icon class="material-icons" [attr.aria-label]="icon">{{ icon }}</mat-icon>
          }
          {{ step.label | breadcrumbLabel }}
        </a>
      } @else {
        <span>
          @if (step.label | breadcrumbIcon; as icon) {
            <mat-icon class="material-icons" [attr.aria-label]="icon">{{ icon }}</mat-icon>
          }
          {{ step.label | breadcrumbLabel }}</span>
      }
      @if (!last) {
        <span class="divider"> > </span>
      }
    </span>
  }
</div>

@switch (headerKind()) {
@case ('lcEvent') {
<div class="tb-cell" flex="30">{{ 'event.event-time' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.server' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.event' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.status' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.error' | translate }}</div>
}
@case ('stats') {
<div class="tb-cell" flex>{{ 'event.event-time' | translate }}</div>
<div class="tb-cell" flex>{{ 'event.server' | translate }}</div>
<div class="tb-cell tb-number" flex>{{ 'event.messages-processed' | translate }}</div>
<div class="tb-cell tb-number" flex>{{ 'event.errors-occurred' | translate }}</div>
}
@case ('error') {
<div class="tb-cell" flex="30">{{ 'event.event-time' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.server' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.method' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.error' | translate }}</div>
}
@case ('debugRuleNode') {
<div hide-xs hide-sm class="tb-cell" flex="25">{{ 'event.event-time' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.server' | translate }}</div>
<div class="tb-cell" flex="10">{{ 'event.type' | translate }}</div>
<div class="tb-cell" flex="15">{{ 'event.entity' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.message-id' | translate }}</div>
<div class="tb-cell" flex="20">{{ 'event.message-type' | translate }}</div>
<div class="tb-cell" flex="15">{{ 'event.relation-type' | translate }}</div>
<div class="tb-cell" flex="10">{{ 'event.data' | translate }}</div>
<div class="tb-cell" flex="10">{{ 'event.metadata' | translate }}</div>
<div class="tb-cell" flex="10">{{ 'event.error' | translate }}</div>
}
}

@if (itemComponent(); as card) {
    <ng-container *ngComponentOutlet="card; inputs: { item: item(), parentCtl: parentCtl() }" />
  }

@if (asButton()) {
  <button mat-raised-button color="primary" type="button" [disabled]="timewindowDisabled" (click)="openEditMode($event)">
    <mat-icon>query_builder</mat-icon>
    <span>{{ model?.displayValue }}</span>
  </button>
} @else {
  <section class="tb-timewindow" layout="row" layout-align="start center">
    @if (direction === 'left') {
      <button mat-icon-button type="button" class="tb-md-32" [disabled]="timewindowDisabled" (click)="openEditMode($event)"
              [attr.aria-label]="'timewindow.edit' | translate"
              [matTooltip]="'timewindow.edit' | translate" [matTooltipPosition]="tooltipPosition">
        <mat-icon [attr.aria-label]="'timewindow.date-range' | translate">query_builder</mat-icon>
      </button>
    }
    <span [hidden]="hideLabel()" (click)="openEditMode($event)"
          [matTooltip]="'timewindow.edit' | translate" [matTooltipPosition]="tooltipPosition">
      {{ model?.displayValue }}
    </span>
    @if (direction === 'right') {
      <button mat-icon-button type="button" class="tb-md-32" [disabled]="timewindowDisabled" (click)="openEditMode($event)"
              [attr.aria-label]="'timewindow.edit' | translate"
              [matTooltip]="'timewindow.edit' | translate" [matTooltipPosition]="tooltipPosition">
        <mat-icon [attr.aria-label]="'timewindow.date-range' | translate">query_builder</mat-icon>
      </button>
    }
  </section>
}
